import assert from "node:assert/strict";
import { createModels, fauxProvider, fauxAssistantMessage } from "@earendil-works/pi-ai";
const faux = fauxProvider();
const models = createModels();
models.setProvider(faux.provider);
faux.setResponses([
  fauxAssistantMessage("hello offline"),
  fauxAssistantMessage("", { stopReason: "error", errorMessage: "injected-error" }),
]);
const context = { messages: [{ role: "user", content: "test", timestamp: Date.now() }] };
const first = await models.complete(faux.getModel(), context);
const second = await models.complete(faux.getModel(), context);
assert.equal(first.stopReason, "stop");
assert.equal(second.stopReason, "error");
assert.match(second.errorMessage, /injected-error/);
assert.equal(typeof first.usage.totalTokens, "number");
console.log({ first: first.stopReason, second: second.stopReason, usage: first.usage });

import assert from "node:assert/strict";
import { normalizeContext, getCurrentSystemPrompt, getCurrentTools } from "@earendil-works/pi-ai";
const echo = { name: "echo", description: "Echo text", parameters: { type: "object" } };
const messages = [
  { role: "system", content: "BASE", sections: { rules: "SHORT" }, toolsAdded: [echo], timestamp: 1 },
  { role: "user", content: "hi", timestamp: 2 },
  { role: "system", content: "", sections: { rules: "LONG" }, toolsRemoved: [{ name: "echo" }], timestamp: 3 },
];
const context = normalizeContext({ messages });
const prompt = getCurrentSystemPrompt(context.messages);
const tools = getCurrentTools(context.messages);
assert.equal(prompt, "BASE\n\nLONG");
assert.deepEqual(tools, []);
assert.equal(messages[0].sections.rules, "SHORT");
console.log({ prompt, tools, originalRules: messages[0].sections.rules });

import assert from "node:assert/strict";
import { Agent } from "@earendil-works/pi-agent-core";
import { createModels, fauxProvider, fauxAssistantMessage } from "@earendil-works/pi-ai";
const faux = fauxProvider();
const models = createModels();
models.setProvider(faux.provider);
faux.setResponses(["first", "steered", "followed"].map(x => fauxAssistantMessage(x)));
let requests = 0, finishes = 0, queued = false;
const agent = new Agent({
  initialState: { model: faux.getModel() },
  streamFn: models.streamSimple.bind(models),
  prepareRequest: async () => { requests++; },
  finishTurn: async () => { finishes++; },
});
agent.subscribe(event => {
  if (!queued && event.type === "message_end" && event.message.role === "assistant") {
    queued = true;
    agent.steer({ role: "user", content: "STEER", timestamp: 2 });
    agent.followUp({ role: "user", content: "FOLLOW", timestamp: 3 });
  }
});
await agent.prompt("START");
const users = agent.state.messages.filter(x => x.role === "user").map(x => typeof x.content === "string" ? x.content : x.content.filter(b => b.type === "text").map(b => b.text).join(""));
assert.deepEqual(users, ["START", "STEER", "FOLLOW"]);
assert.equal(requests, 3);
assert.equal(finishes, 3);
assert.equal(agent.state.isStreaming, false);
console.log({ users, requests, finishes, idle: !agent.state.isStreaming });

import assert from "node:assert/strict";
import { Agent } from "@earendil-works/pi-agent-core";
import { createModels, fauxProvider, fauxAssistantMessage, fauxToolCall } from "@earendil-works/pi-ai";
const models = createModels();
const faux = fauxProvider();
models.setProvider(faux.provider);
let executed = 0;
const echo = {
  name: "echo", label: "Echo", description: "Count executions",
  parameters: { type: "object", properties: { value: { type: "string" } }, required: ["value"] },
  execute: async () => { executed++; return { content: [{ type: "text", text: "ok" }], details: {} }; },
};
faux.setResponses([
  fauxAssistantMessage([fauxToolCall("echo", { value: "hel" })], { stopReason: "length" }),
  fauxAssistantMessage("recovered"),
]);
const agent = new Agent({ initialState: { model: faux.getModel(), tools: [echo] }, streamFn: models.streamSimple.bind(models) });
await agent.prompt("test truncation");
const errors = agent.state.messages.filter(x => x.role === "toolResult" && x.isError);
assert.equal(executed, 0);
assert.equal(errors.length, 1);
const slow = fauxProvider({ tokensPerSecond: 20 });
models.setProvider(slow.provider);
slow.setResponses([fauxAssistantMessage("a deliberately long offline response for cancellation")]);
const cancelled = new Agent({ initialState: { model: slow.getModel() }, streamFn: models.streamSimple.bind(models) });
cancelled.subscribe(event => {
  if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") cancelled.abort();
});
await cancelled.prompt("test abort");
const last = cancelled.state.messages.at(-1);
assert.equal(last.stopReason, "aborted");
console.log({ executed, toolErrors: errors.length, cancelled: last.stopReason });
